  const signalWords = String(item.top_signal ?? '')
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .split(/\W+/)
    .filter((w) => w.length > 4);
  const mentionsCompany = company && lower.includes(company);
  const mentionsSignal = signalWords.some((w) => lower.includes(w));
  if (!mentionsCompany && !mentionsSignal) errors.push('no company or signal reference');

  if ((line.match(/!/g) || []).length > 1) errors.push('too many exclamation marks');
  if (/^(hi|hey|hello|dear)\b/i.test(line)) errors.push('starts with a greeting');

  return errors;
}

const item = $input.item.json;
const errors = check(item);
const attempt = Number(item.qa_attempt ?? 1);

return {
  json: {
    ...item,
    qa_errors: errors,
    qa_status: errors.length === 0 ? 'pass' : attempt < 2 ? 'retry' : 'needs_review',
    qa_attempt: attempt,
  },
};

const acc = $('Final Record').first().json;
const found = $input.first().json;
const hubspotId = found?.results?.[0]?.id ?? null;
const b = acc.brief || {};
const qa = acc.qa_status === 'pass' || acc.qa_status === 'skipped' ? acc.qa_status : 'needs_review';
const properties = {
  name: acc.company_name,
  domain: acc.domain,
  numberofemployees: acc.employees,
  country: acc.country,
  description: acc.description,
  ara_icp_score: acc.icp_score,
  ara_icp_tier: acc.icp_tier,
  ara_top_signal: (acc.top_signal || 'No signal').slice(0, 250),
  ara_first_line: acc.first_line || '',
  ara_research_brief: ['What they do: ' + (b.what_they_do || ''), 'Why now: ' + (b.why_now || ''), 'Angle: ' + (b.angle || '')].join('\n'),
  ara_score_reasons: (acc.score_reasons || []).concat(acc.lookalikes?.length ? ['Closest customers: ' + acc.lookalikes.join(', ')] : []).join('\n'),
  ara_qa_status: qa,
};
return [{ json: { hubspot_id: hubspotId, properties } }];

// A compact row per account. These rows feed the Run Summary.
const acc = $('Final Record').first().json;
const pay = $('Build HubSpot Payload').first().json;
const r = $input.first().json;
const errors = [...(acc.errors || [])];
if (r.error || !r.id) errors.push('hubspot_write_failed');
return [{ json: {
  account_id: acc.account_id, company_name: acc.company_name, domain: acc.domain,
  icp_score: acc.icp_score, icp_tier: acc.icp_tier,
  score_firmographic: acc.score_firmographic, score_signals: acc.score_signals, score_lookalike: acc.score_lookalike,
  lookalike_similarity: acc.lookalike_similarity, lookalikes: acc.lookalikes, top_signal: acc.top_signal,
  why_now: acc.brief?.why_now, first_line: acc.first_line, qa_status: acc.qa_status, qa_attempt: acc.qa_attempt, qa_errors: acc.qa_errors,
  hubspot_id: r.id || pay.hubspot_id, hubspot_action: r.error || !r.id ? 'error' : pay.hubspot_id ? 'updated' : 'created',
  tokens_haiku_in: acc.tokens_haiku_in || 0, tokens_haiku_out: acc.tokens_haiku_out || 0,
  tokens_sonnet_in: acc.tokens_sonnet_in || 0, tokens_sonnet_out: acc.tokens_sonnet_out || 0,
  errors,
} }];
